fullgraph=True implies a "please compile this code, no matter what, and error at me if it didn't compile".
If Dynamo skips due to TorchDispatchMode, it will just fallback to eager, even with fullgraph=True.
import torch
from torch.utils._python_dispatch import TorchDispatchMode

@torch.library.custom_op("mylib::foo", mutates_args=())
def foo(x: torch.Tensor) -> torch.Tensor:
    return x.clone()


_checksums = []

class ChecksumFoo(TorchDispatchMode):
    def __init__(self) -> None:
        super().__init__()

    def __torch_dispatch__(self, func, types, args, kwargs=None):
        kwargs = kwargs or {}

        if func is torch.ops.mylib.foo.default:
            _checksums.append(args[0].abs().sum())

        return func(*args, **kwargs)

@torch.compile(fullgraph=True)
def g(x):
    return x.sin().cos()

x = torch.randn(3)

with ChecksumFoo():
    foo(x)
    g(x)
    foo(x)
